mapper.select:
select assignment.id as id, assignment.account_user_id as accountUserId, account.nick_name as accountNickName, assignment.admin_user_id as adminUserId, admin_user.nick_name as adminNickName, assignment.create_time as createTime from t_copywriting_organization_admin_assignment assignment left join t_user account on account.user_id = assignment.account_user_id left join t_user admin_user on admin_user.user_id = assignment.admin_user_id where assignment.account_user_id in
#{accountUserId}
order by assignment.account_user_id, assignment.create_time, assignment.id

select distinct u.user_id as adminUserId, u.nick_name as adminNickName, u.phone_number as phoneNumber from t_user u inner join t_user_role_map urm on urm.user_id = u.user_id inner join t_role r on r.role_id = urm.role_id where upper(r.name) in ('ORG_ADMIN', 'ADMIN') and coalesce(u.status, 0) = 0
and ( u.nick_name like concat('%', #{keyword}, '%') or u.phone_number like concat('%', #{keyword}, '%') or cast(u.user_id as char) like concat('%', #{keyword}, '%') )
order by u.nick_name, u.user_id limit #{limit}
